package com.learningspace;
import org.json.*;import java.time.*;
public class DailyCoachCheck {
 static void check(boolean value){if(!value)throw new AssertionError();}
 public static void main(String[] args)throws Exception{
  Instant midnight=Instant.parse("2026-10-18T18:30:00Z");check(DailyCoachContext.day(midnight,"Asia/Kolkata").equals("2026-10-18"));check(DailyCoachContext.day(midnight.minusSeconds(1),"Asia/Kolkata").equals("2026-10-17"));
  Instant dst=Instant.parse("2026-03-08T05:00:00Z");check(DailyCoachContext.nextMidnight(dst,"America/New_York")-dst.toEpochMilli()==23*3600000L);
  JSONObject automatic=new JSONObject("{\"activityCalendar\":{\"personal\":[{\"day\":\"2026-10-18\",\"minutes\":10}],\"work\":[]},\"targets\":{\"personalMinutes\":45,\"workMinutes\":30}}");
  JSONObject template=new JSONObject().put("timezone","Asia/Kolkata").put("body",new JSONObject().put("input",new JSONObject().put("snapshotAt","2026-10-18T12:00:00Z").put("reviewDay","OLD").put("context",new JSONObject().put("request","Review my completed day 2026-10-17 honestly.").put("todayBudget",99).put("automatic",automatic).put("screenTime","STALE")).toString()));
  JSONObject input=new JSONObject(DailyCoachContext.request(template,"2026-10-18",midnight).getString("input"));check(input.getString("reviewDay").equals("2026-10-18"));check(input.getJSONObject("dayActivity").getJSONObject("personal").getInt("minutes")==10);check(!input.getJSONObject("context").has("screenTime"));
  JSONObject later=new JSONObject(DailyCoachContext.request(template,"2026-10-22",Instant.parse("2026-10-23T01:00:00Z")).getString("input"));check(later.getJSONObject("dayActivity").getJSONObject("personal").getInt("minutes")==0);
  JSONObject reply=new JSONObject("{\"headline\":\"Reality\",\"assessment\":\"Recorded facts\",\"nextAction\":\"Start a block\",\"checkpoint\":\"A dated note\",\"question\":\"\"}");JSONObject raw=new JSONObject().put("output",new JSONArray().put(new JSONObject().put("content",new JSONArray().put(new JSONObject().put("type","output_text").put("text",reply.toString())))));check(DailyCoachContext.parseReply(raw).getString("headline").equals("Reality"));boolean rejected=false;try{DailyCoachContext.parseReply(new JSONObject());}catch(Exception e){rejected=true;}check(rejected);
  JSONObject day=new JSONObject().put("day","2026-10-18").put("minutes",140).put("measurement",new JSONObject().put("method","unlocked-screen-v1")).put("apps",new JSONArray().put(new JSONObject().put("id","private.package").put("name","Private app").put("minutes",88)));
  JSONObject usage=DailyCoachContext.phoneUsage(day,midnight.toString(),60,false);check(usage.getDouble("totalMinutes")==140);check(!usage.has("leisureMinutes"));check(!usage.toString().contains("private.package"));check(!usage.toString().contains("Private app"));check(DailyCoachContext.phoneUsage(day,midnight.toString(),60,true).getJSONArray("topApps").length()==1);
  check(!input.getJSONObject("context").has("request"));check(!input.getJSONObject("context").has("todayBudget"));check(input.getJSONObject("dateContext").getString("generationDay").equals("2026-10-19"));check(input.getJSONObject("dateContext").getString("reviewDay").equals("2026-10-18"));check(input.getJSONObject("context").getJSONObject("activity").getString("reviewDay").equals("2026-10-18"));
  // Reproduce a template prepared Oct 24 that still asks for Oct 23; the 00:13 job must review Oct 24 everywhere.
  JSONObject cached=new JSONObject(template.toString()),calendar=cached.getJSONObject("body");JSONObject cachedInput=new JSONObject(calendar.getString("input"));cachedInput.put("snapshotAt","2026-10-24T12:00:00Z");JSONObject auto=cachedInput.getJSONObject("context").getJSONObject("automatic");auto.put("continuity",new JSONObject().put("reviewDay","2026-10-23").put("checkpoint","LEGACY_DATE_NOTE"));auto.getJSONObject("activityCalendar").put("personal",new JSONArray().put(new JSONObject().put("day","2026-10-24").put("minutes",40)));cachedInput.getJSONObject("context").put("request","Review my completed day 2026-10-23 honestly.");calendar.put("input",cachedInput.toString());
  Instant generated=Instant.parse("2026-10-24T18:43:18Z");JSONObject actual=new JSONObject(DailyCoachContext.request(cached,"2026-10-24",generated).getString("input"));check(actual.getJSONObject("dayActivity").getJSONObject("personal").getInt("minutes")==40);check(actual.getJSONObject("dateContext").getString("generationDay").equals("2026-10-25"));check(actual.getJSONObject("dateContext").getString("snapshotDay").equals("2026-10-24"));check(!actual.toString().contains("Review my completed day 2026-10-23"));check(!actual.toString().contains("LEGACY_DATE_NOTE"));
  // Fresh post-midnight usage is cut off by activity day, not by the timestamp it was captured.
  actual.getJSONObject("context").put("screenTime",new JSONObject().put("days",new JSONArray().put(new JSONObject().put("day","2026-10-24").put("capturedAt",generated.toString())).put(new JSONObject().put("day","2026-10-25"))));DailyCoachContext.alignInput(actual,"2026-10-24","Asia/Kolkata",generated);check(actual.getJSONObject("context").getJSONObject("screenTime").getJSONArray("days").length()==1);
  JSONObject receipt=new JSONObject().put("id","2026-10-24@Asia/Kolkata").put("activitySignature","same").put("at",generated.toString());check(!DailyCoachContext.canReuse(receipt,"2026-10-24@Asia/Kolkata","same"));receipt.put("requestVersion",2);check(DailyCoachContext.canReuse(receipt,"2026-10-24@Asia/Kolkata","same"));check(!DailyCoachContext.canReuse(receipt,"2026-10-24@Asia/Kolkata","changed"));String previous=DailyCoachContext.noticeKey(receipt);receipt.put("at",generated.plusSeconds(1).toString());check(!previous.equals(DailyCoachContext.noticeKey(receipt)));
  System.out.println("Daily coach: local midnight, DST, completed-day totals, total phone time, private app names, stale usage removal, cached request date rollover, receipt versioning, updated notifications and reply validation passed.");
 }
}
